def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value or ""
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)

        value = value.strip().lower()

        if value.count("@") == 1:
            local, domain = value.split("@")
            if domain in {"gmail.com", "googlemail.com"}:
                local = local.split("+", 1)[0].replace(".", "")
                value = local + "@gmail.com"

        return value

    def valid_email(value):
        if value.count("@") != 1:
            return False
        local, domain = value.split("@")
        return (
            bool(local)
            and "." in domain
            and not domain.startswith(".")
            and not domain.endswith(".")
        )

    def normalize_phone(value):
        value = value or ""
        marker = re.search(r"(?:ext|x|#)", value, flags=re.IGNORECASE)
        if marker:
            value = value[:marker.start()]

        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]

        if len(digits) != 10 or digits[0] in {"0", "1"}:
            return ""
        return digits

    def normalize_zip(value):
        value = (value or "").strip()

        zip_plus_four = re.fullmatch(r"(\d{5})-\d{4}", value)
        if zip_plus_four:
            value = zip_plus_four.group(1)

        if re.fullmatch(r"\d{4}", value):
            value = "0" + value

        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = (value or "").strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError("Invalid updated value: {!r}".format(value))

    def is_opted_out(value):
        return (value or "").strip().lower() in {
            "y", "yes", "true", "1"
        }

    normalized_rows = []

    for input_index, row in enumerate(rows):
        email = normalize_email(row.get("email", ""))
        if not valid_email(email):
            email = ""

        phone = normalize_phone(row.get("phone", ""))

        # Drop rows without either a valid email or valid phone.
        if not email and not phone:
            continue

        tags = {
            tag.strip().lower()
            for tag in re.split(r"[;,]", row.get("tags", "") or "")
            if tag.strip()
        }

        source = (row.get("source", "") or "").strip().lower()

        normalized_rows.append({
            "input_index": input_index,
            "first_name": normalize_name(row.get("first_name", "")),
            "last_name": normalize_name(row.get("last_name", "")),
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row.get("zip", "")),
            "tags": tags,
            "opted_out": is_opted_out(row.get("opted_out", "")),
            "updated": parse_updated(row["updated"]),
            "source": source,
        })

    count = len(normalized_rows)
    parent = list(range(count))
    rank = [0] * count

    def find(index):
        while parent[index] != index:
            parent[index] = parent[parent[index]]
            index = parent[index]
        return index

    def union(left, right):
        left_root = find(left)
        right_root = find(right)

        if left_root == right_root:
            return

        if rank[left_root] < rank[right_root]:
            left_root, right_root = right_root, left_root

        parent[right_root] = left_root
        if rank[left_root] == rank[right_root]:
            rank[left_root] += 1

    email_owner = {}
    phone_last_name_owner = {}

    for index, row in enumerate(normalized_rows):
        if row["email"]:
            previous = email_owner.get(row["email"])
            if previous is None:
                email_owner[row["email"]] = index
            else:
                union(index, previous)

        last_name_key = row["last_name"].casefold()
        if row["phone"] and last_name_key:
            key = (row["phone"], last_name_key)
            previous = phone_last_name_owner.get(key)
            if previous is None:
                phone_last_name_owner[key] = index
            else:
                union(index, previous)

    groups = {}
    for index, row in enumerate(normalized_rows):
        groups.setdefault(find(index), []).append(row)

    def choose_field(group, field):
        candidates = [row for row in group if row[field]]
        if not candidates:
            return ""

        best = min(
            candidates,
            key=lambda row: (
                0 if row["source"] == "manual" else 1,
                -row["updated"].timestamp(),
                row["input_index"],
            ),
        )
        return best[field]

    output = []

    for group in sorted(
        groups.values(),
        key=lambda members: min(row["input_index"] for row in members),
    ):
        all_tags = set()
        for row in group:
            all_tags.update(row["tags"])

        latest_updated = max(row["updated"] for row in group)

        output.append({
            "first_name": choose_field(group, "first_name"),
            "last_name": choose_field(group, "last_name"),
            "zip": choose_field(group, "zip"),
            "email": choose_field(group, "email"),
            "phone": choose_field(group, "phone"),
            "source": choose_field(group, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": (
                "Y" if any(row["opted_out"] for row in group) else "N"
            ),
            "updated": latest_updated.strftime("%Y-%m-%d"),
        })

    return output
